item.command:
"<USER_HOME>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command '
$ErrorActionPreference = '"'Stop'
"'$taskRoot = '"'D:\\tx-harness-participants\\pilot_attempt02-codex-T01-r1'
function Select-Latest("'$rows, $idColumn) {
    $unique = @($rows | Group-Object -Property $idColumn,revision | ForEach-Object { $_.Group[0] })
    $latest = @($unique | Group-Object -Property $idColumn | ForEach-Object { $_.Group | Sort-Object { [int]$_.revision } -Descending | Select-Object -First 1 })
    return @{ latest=$latest; duplicates=($rows.Count-$unique.Count); superseded=($unique.Count-$latest.Count) }
}
$orders = @([IO.File]::ReadAllText("$taskRoot'"\\inputs\\orders.csv\") | ConvertFrom-Csv)
"'$refunds = @([IO.File]::ReadAllText("$taskRoot'"\\inputs\\refunds.csv\") | ConvertFrom-Csv)
"'$o = Select-Latest $orders '"'order_id'
"'$r = Select-Latest $refunds '"'refund_id'
"'$orderMap = @{}
$refundAmounts = @{}
foreach ($order in $o.latest) { $orderMap[$order.order_id] = $order }
$orphan = @()
$nonSuccess = @()
$ineligible = @()
foreach ($refund in $r.latest) {
    if (-not $orderMap.ContainsKey($refund.order_id)) { $orphan += $refund.refund_id }
    elseif ($refund.status -cne '"'success') { "'$nonSuccess += $refund.refund_id }
    elseif ($orderMap[$refund.order_id].status -cnotin @('"'paid','shipped')) { "'$ineligible += $refund.refund_id }
    else { $refundAmounts[$refund.order_id] += [long]$refund.amount_cents }
}
$ledger = @($o.latest | Sort-Object order_id | ForEach-Object {
    $included = $_.status -cin @('"'paid','shipped')
    "'$refund = if ($included) { [long]$refundAmounts[$_.order_id] } else { 0L }
    $net = if ($included) { [long]$_.gross_cents - $refund } else { 0L }
    [pscustomobject][ordered]@{order_id=$_.order_id; customer_group=$_.customer_group; status=$_.status; gross_cents=[long]$_.gross_cents; successful_refund_cents=$refund; net_cents=$net; included=$included.ToString().ToLowerInvariant()}
})
function Get-Totals($rows) {
    $gross=0L; $refund=0L; $net=0L
    foreach ($row in $rows) { $gross += $row.gross_cents; $refund += $row.successful_refund_cents; $net += $row.net_cents }
    return [ordered]@{order_count=@($rows).Count; gross_cents=$gross; refund_cents=$refund; net_cents=$net}
}
$selected = @($ledger | Where-Object included -CEQ '"'true')
"'$groups = @($selected | Group-Object customer_group | Sort-Object Name | ForEach-Object {
    $totals = Get-Totals $_.Group
    [ordered]@{customer_group=$_.Name; order_count=$totals.order_count; gross_cents=$totals.gross_cents; refund_cents=$totals.refund_cents; net_cents=$totals.net_cents}
})
$aggregate = [ordered]@{total=(Get-Totals $selected); groups=$groups}
$exceptions = [ordered]@{
exact_duplicate_order_rows=$o.duplicates; superseded_order_rows=$o.superseded
exact_duplicate_refund_rows=$r.duplicates; superseded_refund_rows=$r.superseded
orphan_refund_ids=@($orphan | Sort-Object -CaseSensitive)
ignored_non_success_refund_ids=@($nonSuccess | Sort-Object -CaseSensitive)
ignored_ineligible_order_refund_ids=@($ineligible | Sort-Object -CaseSensitive)
}
[IO.Directory]::CreateDirectory("$taskRoot'"\\outputs\") | Out-Null
[IO.File]::WriteAllLines(\""'$taskRoot'"\\outputs\\order_ledger.csv\", [string[]]@("'$ledger | ConvertTo-Csv -NoTypeInformation), [Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText("$taskRoot'"\\outputs\\aggregate.json\", ("'$aggregate | ConvertTo-Json -Depth 10), [Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText("$taskRoot'"\\outputs\\exceptions.json\", ("'$exceptions | ConvertTo-Json -Depth 10), [Text.UTF8Encoding]::new($false))
$readLedger = @([IO.File]::ReadAllText("$taskRoot'"\\outputs\\order_ledger.csv\") | ConvertFrom-Csv)
"'$readAggregate = [IO.File]::ReadAllText("$taskRoot'"\\outputs\\aggregate.json\") | ConvertFrom-Json
"'$readExceptions = [IO.File]::ReadAllText("$taskRoot'"\\outputs\\exceptions.json\") | ConvertFrom-Json
if ("'$readLedger.Count -ne 6 -or @($readLedger | Group-Object order_id | Where-Object Count -ne 1).Count -ne 0) { throw '"'Ledger key validation failed' }
if ("'$readAggregate.total.order_count -ne 4 -or $readAggregate.total.gross_cents -ne 50300 -or $readAggregate.total.refund_cents -ne 7000 -or $readAggregate.total.net_cents -ne 43300) { throw '"'Aggregate validation failed' }
"'$readAggregate | ConvertTo-Json -Depth 10
$readExceptions | ConvertTo-Json -Depth 10
'
